"""Generate starling2.sdf (Gazebo Classic) from iris_starling.sdf: swap meshes, rotor geometry, collision, mass/inertia."""
import re, sys
src=open('iris_starling/iris_starling.sdf').read()
s=src
s=s.replace("<!-- DO NOT EDIT: Generated from iris.sdf.jinja -->",
 "<!-- Generated by cad/scripts/04_make_sdf.py from iris_starling.sdf + ModalAI D0014 Starling 2-C26 STEP. Edit the script, not this file. -->")
s=s.replace("<model name='iris'>","<model name='starling2'>")
# mass / inertia (box estimate 0.155 x 0.198 x 0.085 m, 0.285 kg take-off weight incl. battery)
s=s.replace("<mass>0.275</mass>","<mass>0.285</mass>",1)
s=re.sub(r"<ixx>0.005333</ixx>","<ixx>0.001103</ixx>",s,1)
s=re.sub(r"<iyy>0.005333</iyy>","<iyy>0.000742</iyy>",s,1)
s=re.sub(r"<izz>0.010115</izz>","<izz>0.001502</izz>",s,1)
# body collision box -> real envelope (legs bottom at z=-0.030, top of GPS mast z=+0.055)
s=s.replace("<size>0.30 0.35 0.08</size>","<size>0.155 0.198 0.085</size>")
s=s.replace("""      <collision name='base_link_inertia_collision'>
        <pose>0 0 0 0 0 0</pose>""","""      <collision name='base_link_inertia_collision'>
        <pose>0 0 0.0125 0 0 0</pose>""")
# body mesh
s=s.replace("<uri>model://iris/meshes/iris.stl</uri>","<uri>model://starling2/meshes/starling2_body.stl</uri>")
# rotor poses: PX4 order 0=front-right 1=rear-left 2=front-left 3=rear-right ; gazebo y is LEFT
poses={"0.15 -0.25 0.023":"0.066 -0.088 0.0174","-0.15 0.19 0.023":"-0.066 0.088 0.0174",
       "0.15 0.25 0.023":"0.066 0.088 0.0174","-0.15 -0.19 0.023":"-0.066 -0.088 0.0174"}
for a,b in poses.items():
    assert f"<pose>{a} 0 0 0</pose>" in s, a
    s=s.replace(f"<pose>{a} 0 0 0</pose>",f"<pose>{b} 0 0 0</pose>")
# rotor collision cylinder radius 0.128 -> 0.06 (120 mm prop)
s=s.replace("<radius>0.128</radius>","<radius>0.06</radius>")
# prop meshes (a = used where iris had ccw, b = mirrored)
s=s.replace("<uri>model://iris/meshes/iris_prop_ccw.dae</uri>","<uri>model://starling2/meshes/starling2_prop_a.stl</uri>")
s=s.replace("<uri>model://iris/meshes/iris_prop_cw.dae</uri>","<uri>model://starling2/meshes/starling2_prop_b.stl</uri>")
# rotor inertia: 120mm prop ~2 g -> thin rod about hub
s=re.sub(r"<mass>0.005</mass>","<mass>0.002</mass>",s)
s=s.replace("<iyy>0.000273104</iyy>","<iyy>2.4e-06</iyy>").replace("<izz>0.000274004</izz>","<izz>2.5e-06</izz>").replace("<ixx>9.75e-07</ixx>","<ixx>2e-07</ixx>")
# materials
s=s.replace("<name>Gazebo/DarkGrey</name>","<name>Gazebo/Black</name>")
s=s.replace("<name>Gazebo/Blue</name>","<name>Gazebo/Grey</name>")
# gps model pose -> top of mast
s=s.replace("<pose>0.05 0 0.04 0 0 0</pose>","<pose>0 0 0.05 0 0 0</pose>")
assert "iris" not in s.replace("iris_starling",""), [m.start() for m in re.finditer("iris",s)]
open('starling2/starling2.sdf','w').write(s)
print("written starling2/starling2.sdf, lines:", s.count("\n"))
